import Image from "next/image";
import Link from "next/link";
import { cn } from "@/lib/cn";

/**
 * Official Localians artwork (public/images/logo; sizes generated by scripts/build-brand-assets.mjs).
 * The wordmark's "Local" and globe are white, made for dark backgrounds; `-light` is the same
 * artwork re-inked for light backgrounds (the dashboard's light theme).
 */
const WORDMARK = { width: 640, height: 106, dark: "/images/logo/localians-logo-640.png", light: "/images/logo/localians-logo-light-640.png" };
const MARK = "/images/logo/localians-mark-256.png";

type Variant = "dark" | "theme";

/** The wordmark at a fixed height (width follows the artwork's proportions — never stretched). */
export function Wordmark({ height = 26, variant = "dark", priority = false, className }: { height?: number; variant?: Variant; priority?: boolean; className?: string }) {
  const width = Math.round((height * WORDMARK.width) / WORDMARK.height);
  const common = { width: WORDMARK.width, height: WORDMARK.height, priority, sizes: `${width}px`, style: { width, height } } as const;
  return (
    <span className={cn("relative inline-flex shrink-0", className)} style={{ width, height }}>
      <Image src={WORDMARK.dark} alt="Localians" {...common} className={variant === "theme" ? "brand-on-dark" : undefined} />
      {/* Light-theme version: only shown inside a light `.theme-scope` (see globals.css). */}
      {variant === "theme" ? <Image src={WORDMARK.light} alt="" aria-hidden="true" {...common} className="brand-on-light" /> : null}
    </span>
  );
}

/** The square mark alone (lime C with globe). */
export function LogoMark({ size = 24, className }: { size?: number; className?: string }) {
  return <Image src={MARK} alt="" aria-hidden="true" width={256} height={256} sizes={`${size}px`} style={{ width: size, height: size }} className={cn("shrink-0", className)} />;
}

export function Logo({ className, href = "/", height = 26, variant = "dark", priority = false }: { className?: string; href?: string; height?: number; variant?: Variant; priority?: boolean }) {
  return (
    <Link href={href} aria-label="Localians home" className={cn("inline-flex items-center transition-opacity hover:opacity-90", className)}>
      <Wordmark height={height} variant={variant} priority={priority} />
    </Link>
  );
}
